{"path": "task/workspace/app/meta.go", "start": 1, "lines": 28, "offset": 0, "total_lines": 28, "content": "package app

import (
	"fyne.io/fyne/v2"
)

var (
	// appMetadata holds the current application metadata
	appMetadata = fyne.AppMetadata{
		ID:      "com.example",
		Name:    "Fyne App",
		Version: "1.0.0",
		Build:   1,
	}
)

// SetMetadata sets the application metadata for the running app.
// This overrides the default metadata.
//
// Since: 2.5
func SetMetadata(m fyne.AppMetadata) {
	appMetadata = m
}

// Metadata returns the application metadata.
func (a *fyneApp) Metadata() fyne.AppMetadata {
	return appMetadata
}
