package desktop

import (
	"fyne.io/fyne/v2"
)

// DesktopApp defines an interface for desktop applications with system tray support.
//
// Since: 2.5
type DesktopApp interface {
	// SetSystemTrayMenu sets the system tray menu for the application.
	// The menu will be displayed when the user interacts with the system tray icon.
	//
	// Since: 2.5
	SetSystemTrayMenu(menu *fyne.Menu)

	// SetSystemTrayIcon sets the icon to be displayed in the system tray.
	// Pass nil to remove the system tray icon.
	//
	// Since: 2.5
	SetSystemTrayIcon(icon fyne.Resource)
}
